// TH14 synthetic training aliases (see transcribe/th14/touhou-bullets.ecl).
// Native type 25 -> modern row 768; base radius 6, colors 0-15.
const TH14_FIREBALL_PURPLE: int = 768;

// th14_s5_b2 - TH14 v1.00b st05bs.ecl.txt BossCard1 (source lines 482-535).
// Entry sub BossCard1; attack children BossCard1_at (537-577) and, on Hard/Lunatic,
// BossCard1_at_l (579-623). Source bullet type 25 -> TH14_FIREBALL_PURPLE (row 768), color 3.
// Omitted per policy: BossItemCard rewards, Ecl_EtBreak/entry cleanup (standalone start has
// no prior bullets/tasks), anm/playSound presentation, funcSet(0) (no callback installed),
// funcCall(2) screen-fx, and the ANIM/BRIGHT EX records (visual only).

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// Source interrupt is 2100 frames from timerReset; the async children start at t=300,
// so they stop on their own clock at t=2100 (source timeout boundary).
const ATTACK_WINDOW: int = 1800;

// moveRand(60, 0, 0.6) under moveLimit(0, 128, 280, 64):
// clamp x in [-140,140], y in [96,160]; direction inner region x +/-70, y 112..144.
// Same per-frame arming recipe as the verified TH16/TH18 sample, with speed 0.6.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx / 60) * 0.6fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source signed unit random * pi, unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// BossCard1_at: one bullet per iteration, aim mode 1 (fixed direction) with 1 way/1 layer.
// alpha = pi/2 + RANDF2*5deg; offsetAbs x = A + RANDF2*16, y = RANDF*64, A starts -192, +32/shot;
// speed = 1.4 + RANDF*C, C ramps 0..1 in steps of 0.1 then stays at 1.
// Cast valid until the source timeout (2100 - 300 = 1800 frames).
async sub boss_card1_at() {
    sh_reset(0);
    sh_sprite(0, TH14_FIREBALL_PURPLE, 3);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    var shots: int = 13;
    var gap: int = 3;
    if global(GVAR_RANK) == RANK_EASY { shots = 15; gap = 6; }
    var level: int = 0;
    var elapsed: int = 0;
    var a: fx = -192fx;
    while elapsed < ATTACK_WINDOW {
        a = -192fx;
        var spread: fx = (level as fx) / 10;
        var i: int = 0;
        while i < shots {
            if elapsed >= ATTACK_WINDOW { return; }
            // Source samples: angle RANDF2, x RANDF2, y RANDF, speed RANDF.
            var ar: int = rand(65535) - 32767;
            var ang: angle = (16384 + (ar * 910) / 32768) as angle;
            var xr: int = rand(65535) - 32767;
            var yr: int = rand(32768);
            var u: fx = (rand(32768) as fx) / 32768;
            var sp: fx = 1.4fx + u * spread;
            // Birth ANIM keeps position -= 4*velocity (source EX type 2 at a=1).
            var vel4: fx = 4fx * sp;
            sh_angle(0, ang, 0deg);
            // 628 etOffsetAbs: absolute spawn position, not owner-relative.
            sh_offset_abs(0,
                a + ((xr as fx) / 32768) * 16fx - vel4 * cos(ang),
                ((yr as fx) / 32768) * 64fx - vel4 * sin(ang));
            sh_speed(0, sp, 0fx);
            sh_fire(0);
            a = a + 32fx;
            i = i + 1;
            wait(gap);
            elapsed = elapsed + gap;
        }
        if level < 10 { level = level + 1; }
    }
}

// BossCard1_at_l (Hard/Lunatic only): two bullets per iteration from x = -192 and x = +192,
// y = RANDF*180; alpha1 = 1.1780972 + RANDF2*(pi/4), alpha2 = 1.9634954 + RANDF2*(pi/4);
// speed = 1.4 + RANDF*C with the same 0..1 ramp.
async sub boss_card1_at_l() {
    sh_reset(0);
    sh_sprite(0, TH14_FIREBALL_PURPLE, 3);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    var shots: int = 6;
    var gap: int = 6;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { shots = 3; gap = 3; }
    if rank == RANK_HARD { shots = 16; gap = 16; }
    var level: int = 0;
    var elapsed: int = 0;
    while elapsed < ATTACK_WINDOW {
        var spread: fx = (level as fx) / 10;
        var i: int = 0;
        while i < shots {
            if elapsed >= ATTACK_WINDOW { return; }
            // Bullet 1: angle RANDF2, y RANDF, speed RANDF.
            var ar1: int = rand(65535) - 32767;
            var ang1: angle = (12288 + (ar1 * 8192) / 32768) as angle;
            var y1r: int = rand(32768);
            var u1: fx = (rand(32768) as fx) / 32768;
            var sp1: fx = 1.4fx + u1 * spread;
            var v1: fx = 4fx * sp1;
            sh_angle(0, ang1, 0deg);
            sh_offset_abs(0, -192fx - v1 * cos(ang1), ((y1r as fx) / 32768) * 180fx - v1 * sin(ang1));
            sh_speed(0, sp1, 0fx);
            sh_fire(0);
            // Bullet 2: angle RANDF2, y RANDF, speed RANDF.
            var ar2: int = rand(65535) - 32767;
            var ang2: angle = (20480 + (ar2 * 8192) / 32768) as angle;
            var y2r: int = rand(32768);
            var u2: fx = (rand(32768) as fx) / 32768;
            var sp2: fx = 1.4fx + u2 * spread;
            var v2: fx = 4fx * sp2;
            sh_angle(0, ang2, 0deg);
            sh_offset_abs(0, 192fx - v2 * cos(ang2), ((y2r as fx) / 32768) * 180fx - v2 * sin(ang2));
            sh_speed(0, sp2, 0fx);
            sh_fire(0);
            i = i + 1;
            wait(gap);
            elapsed = elapsed + gap;
        }
        if level < 10 { level = level + 1; }
    }
}

// Boss movement/phases after the entry state: position anchor (0,128), movePosTime(60,4,0,144),
// then the moveRand(60,0,0.6)/wait(120) loop starting at t=480.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(48fx);
    set_hurtbox(48fx);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    wait(60);   // t=120 anmSelectedPlay (presentation)
    wait(30);   // t=150 EffChargePoint3/anmPlay/sound (presentation)
    wait(90);   // t=240 sound/I0/funcCall(2) omitted
    wait(60);   // t=300
    spawn boss_card1_at();
    if global(GVAR_RANK) >= RANK_HARD { spawn boss_card1_at_l(); }
    wait(180);  // t=480
    for i in 0..13 {
        card_move_rand();
        card_wait(120);
    }
    card_move_rand();   // t=2040
    card_wait(60);      // to source t=2100
    // Next-attack entry (Boss2) on the timeout path clears the field (etClear 640).
    clear_bullets_at(0fx, 0fx, 640fx, 0);
    loop { wait(60); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2600, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
